function eqSlot(Slot _a, Slot _b) pure returns (bool) {
    return Slot.unwrap(_a) == Slot.unwrap(_b);
}
function neqSlot(Slot _a, Slot _b) pure returns (bool) {
    return Slot.unwrap(_a) != Slot.unwrap(_b);
}
function gteSlot(Slot _a, Slot _b) pure returns (bool) {
    return Slot.unwrap(_a) >= Slot.unwrap(_b);
}
